def reprendre_les_photos(apps, schema_editor):
    """La photo unique de chaque chambre devient sa première photo (le fichier ne bouge pas)."""
    Chambre = apps.get_model("hotel", "Chambre")
    PhotoChambre = apps.get_model("hotel", "PhotoChambre")
    for chambre in Chambre.objects.exclude(photo=""):
        PhotoChambre.objects.create(chambre=chambre, image=chambre.photo.name, ordre=0)


def remettre_la_photo(apps, schema_editor):
    Chambre = apps.get_model("hotel", "Chambre")
    PhotoChambre = apps.get_model("hotel", "PhotoChambre")
    for chambre in Chambre.objects.all():
        premiere = PhotoChambre.objects.filter(chambre=chambre).order_by("ordre", "pk").first()
        if premiere:
            Chambre.objects.filter(pk=chambre.pk).update(photo=premiere.image.name)


